import {supabase,currentUser,accountUrl} from './auth-client.mjs';
import {inventoryStatus} from './album-model.mjs';
const $=id=>document.getElementById(id),root=new URL('./album-data/',import.meta.url),el=(t,s,c)=>{const n=document.createElement(t);if(s!==undefined)n.textContent=s;if(c)n.className=c;return n;};
let data,user,ready=false,gold=false,revision=0;const inventory=new Map(),priorities=new Map(),pending=new Set();
function message(s){$('album-status').textContent=s;}
function progress(){if(!ready){$('album-progress').textContent='135 Cards · 15 Sets';return;}const owned=data.cards.filter(c=>(inventory.get(c.number)?.quantity||0)>0).length;$('album-progress').textContent=owned+'/135 Collected · '+(135-owned)+' Missing';}
function cardTile(card){const record=inventory.get(card.number),q=record?.quantity||0,state=inventoryStatus(card,q,gold),tile=el('article',undefined,'album-card'+(state.owned?' collected':''));tile.dataset.card=card.number;const art=el('img');art.src=new URL(card.image,root);art.alt=card.name;art.loading='lazy';art.className='card-art';const title=el('h3','#'+card.number+' · '+card.name);tile.append(art,title,el('p','★'.repeat(card.stars)+(card.gold?' · Gold':''),'card-stars'),el('span',ready?state.label:'—','card-trade-status'));
 const controls=el('div',undefined,'quantity-controls'),minus=el('button'),plus=el('button'),count=el('strong',ready?'Owned: '+q:'Owned: —');for(const [button,delta] of [[minus,-1],[plus,1]]){button.type='button';button.className='quantity-button';button.setAttribute('aria-label',(delta===1?'Add':'Remove')+' card '+card.number);const symbol=el('img');symbol.src=new URL('ui/'+(delta===1?'plus.png':'minus.png'),root);symbol.alt='';button.append(symbol);button.disabled=!ready||pending.has(card.number)||(delta===-1?q===0:q===999);button.onclick=()=>adjust(card,delta);}controls.append(minus,count,plus);tile.append(controls);if(card.gold&&!gold)tile.append(el('p','Gold Exchange locked','gold-locked'));if(record?.updated_at){const date=new Date(record.updated_at),time=el('time','Updated '+date.toLocaleString(),'inventory-updated');time.dateTime=date.toISOString();tile.append(time);}return tile;}
function render(){progress();const set=$('set-filter').value,filter=$('card-filter').value,query=$('card-search').value.trim().toLowerCase(),groups=[...data.sets].sort((a,b)=>(priorities.get(b.number)||2)-(priorities.get(a.number)||2)||a.number-b.number);const output=[];for(const group of groups){if(set!=='all'&&Number(set)!==group.number)continue;const cards=data.cards.filter(c=>c.set===group.number&&(!query||String(c.number).includes(query)||c.name.toLowerCase().includes(query))).filter(c=>{const n=inventory.get(c.number)?.quantity||0;return filter==='all'||filter==='missing'&&n===0||filter==='duplicates'&&n>=2||filter==='gold'&&c.gold;});if(!cards.length)continue;const section=el('section',undefined,'album-set'),header=el('div',undefined,'album-set-heading'),priority=el('select');priority.setAttribute('aria-label','Priority for '+group.name);for(const [value,name] of [[3,'High Priority'],[2,'Normal Priority'],[1,'Low Priority']])priority.append(new Option(name,value));priority.value=priorities.get(group.number)||2;priority.disabled=!ready;priority.onchange=async()=>{priority.disabled=true;const selected=Number(priority.value);const {error}=await supabase.from('album_priorities').upsert({user_id:user.id,season_id:data.season,set_number:group.number,priority:selected},{onConflict:'user_id,season_id,set_number'});if(error){message(error.message);priority.value=priorities.get(group.number)||2;priority.disabled=false;}else{priorities.set(group.number,selected);render();}};const owned=group.cards.filter(n=>(inventory.get(n)?.quantity||0)>0).length;header.append(el('h2',group.number+'. '+group.name),el('span',ready?owned+'/9':''),priority);const grid=el('div',undefined,'album-card-grid');grid.append(...cards.map(cardTile));section.append(header,el('p',group.rewards.join(' · '),'set-rewards'),grid);output.push(section);}if(!output.length)output.push(el('p','No cards match your filters.'));$('album-sets').replaceChildren(...output);}
async function adjust(card,delta){if(!ready||pending.has(card.number))return;const token=revision;pending.add(card.number);const tile=document.querySelector('[data-card="'+card.number+'"]');tile.querySelectorAll('button').forEach(b=>b.disabled=true);try{const {data:rows,error}=await supabase.rpc('album_adjust_quantity',{p_season:data.season,p_card:card.number,p_delta:delta});if(error)throw error;if(token!==revision)return;if(!rows?.length)throw Error('Quantity could not be confirmed.');inventory.set(card.number,rows[0]);message('Saved.');}catch(error){message('Could not save: '+error.message);}finally{pending.delete(card.number);render();}}
async function load(){if(!data)return;const token=++revision;ready=false;inventory.clear();priorities.clear();$('save-trade-preferences').disabled=true;try{user=await currentUser();const status=await supabase.rpc('album_exchange_status',{p_season:data.season});if(token!==revision)return;gold=!status.error&&status.data===true;$('gold-status').textContent=gold?'Gold Exchange active · all gold cards':'Gold Exchange locked';if(!user){message('Log in through Account to track your cards.');render();return;}message('Loading your collection…');const [cards,prefs,priority]=await Promise.all([supabase.from('card_inventory').select('card_number,quantity,updated_at').eq('user_id',user.id).eq('season_id',data.season),supabase.from('album_trade_preferences').select('accept_equal,accept_up,accept_down,accept_any').eq('user_id',user.id).eq('season_id',data.season).maybeSingle(),supabase.from('album_priorities').select('set_number,priority').eq('user_id',user.id).eq('season_id',data.season)]);if(token!==revision)return;for(const r of [cards,prefs,priority])if(r.error)throw r.error;for(const c of cards.data)inventory.set(c.card_number,c);for(const p of priority.data)priorities.set(p.set_number,p.priority);for(const k of ['equal','up','down','any'])$('trade-'+k).checked=prefs.data?.['accept_'+k]??(k==='equal');ready=true;$('save-trade-preferences').disabled=false;message('Changes save automatically.');render();}catch(error){message('Album database setup is needed or unavailable: '+error.message);render();}}
$('save-trade-preferences').onclick=async()=>{if(!ready)return;$('save-trade-preferences').disabled=true;const row={user_id:user.id,season_id:data.season};for(const k of ['equal','up','down','any'])row['accept_'+k]=$('trade-'+k).checked;const {error}=await supabase.from('album_trade_preferences').upsert(row,{onConflict:'user_id,season_id'});$('trade-status').textContent=error?error.message:'Trade preferences saved.';$('save-trade-preferences').disabled=false;};
for(const id of ['set-filter','card-filter'])$(id).onchange=render;$('card-search').oninput=render;supabase.auth.onAuthStateChange(()=>setTimeout(load,0));
try{const response=await fetch(new URL('autumn-tales.json',root));if(!response.ok)throw Error('Album data could not load.');data=await response.json();for(const s of data.sets)$('set-filter').append(new Option(s.number+'. '+s.name,s.number));render();await load();}catch(error){message(error.message);}

setInterval(async()=>{if(!data)return;const {data:active,error}=await supabase.rpc('album_exchange_status',{p_season:data.season});const next=!error&&active===true;if(next!==gold){gold=next;$('gold-status').textContent=gold?'Gold Exchange active · all gold cards':'Gold Exchange locked';render();}},60000);
